export * from "./empty";
export * as Empty from "./namespace";
export * from "./styles";

import type { VariantProps } from "cva";
import { EmptyStyles } from "./styles";

export interface EmptyRootProps extends React.ComponentProps<"div"> {}

export function EmptyRoot({ className, ...props }: EmptyRootProps) {
  return (
    <div
      className={EmptyStyles.Root({ className })}
      data-slot="empty"
      {...props}
    />
  );
}

export interface EmptyHeaderProps extends React.ComponentProps<"div"> {}

export function EmptyHeader({ className, ...props }: EmptyHeaderProps) {
  return (
    <div
      className={EmptyStyles.Header({ className })}
      data-slot="empty-header"
      {...props}
    />
  );
}

export interface EmptyMediaProps
  extends React.ComponentProps<"div">,
    VariantProps<typeof EmptyStyles.Media> {}

export function EmptyMedia({
  className,
  variant = "default",
  ...props
}: EmptyMediaProps) {
  return (
    <div
      className={EmptyStyles.Media({ variant, className })}
      data-slot="empty-icon"
      data-variant={variant}
      {...props}
    />
  );
}

export interface EmptyTitleProps extends React.ComponentProps<"div"> {}

export function EmptyTitle({ className, ...props }: EmptyTitleProps) {
  return (
    <div
      className={EmptyStyles.Title({ className })}
      data-slot="empty-title"
      {...props}
    />
  );
}

export interface EmptyDescriptionProps extends React.ComponentProps<"p"> {}

export function EmptyDescription({
  className,
  ...props
}: EmptyDescriptionProps) {
  return (
    <div
      className={EmptyStyles.Description({ className })}
      data-slot="empty-description"
      {...props}
    />
  );
}

export interface EmptyContentProps extends React.ComponentProps<"div"> {}

export function EmptyContent({ className, ...props }: EmptyContentProps) {
  return (
    <div
      className={EmptyStyles.Content({ className })}
      data-slot="empty-content"
      {...props}
    />
  );
}

import { cva } from "~/registry/lib/cva";

export const EmptyStyles = {
  Root: cva({
    base: [
      "flex w-full min-w-0 flex-1 flex-col items-center justify-center gap-4",
      "text-balance rounded-xl border-dashed p-6 text-center",
    ],
  }),
  Header: cva({
    base: ["flex max-w-sm flex-col items-center gap-2"],
  }),
  Media: cva({
    base: [
      "mb-2 flex shrink-0 items-center justify-center",
      "[&_svg]:pointer-events-none [&_svg]:shrink-0",
    ],
    variants: {
      variant: {
        default: "bg-transparent",
        icon: [
          "flex size-8 shrink-0 items-center justify-center rounded-lg bg-muted text-foreground",
          "[&_svg:not([class*='size-'])]:size-4",
        ],
      },
    },
    defaultVariants: {
      variant: "default",
    },
  }),
  Title: cva({
    base: ["font-medium text-sm tracking-tight"],
  }),
  Description: cva({
    base: [
      "text-muted-foreground text-sm/relaxed",
      "[&>a:hover]:text-primary [&>a]:underline [&>a]:underline-offset-4",
    ],
  }),
  Content: cva({
    base: [
      "flex w-full min-w-0 max-w-sm flex-col items-center gap-2.5 text-balance text-sm",
    ],
  }),
};

export {
  EmptyContent as Content,
  EmptyDescription as Description,
  EmptyHeader as Header,
  EmptyMedia as Media,
  EmptyRoot as Root,
  EmptyTitle as Title,
} from "./empty";
